303	struct Out {
304	    status: u16,
305	    content_type: &'static str,
306	    body: String,
307	    headers: Vec<(&'static str, String)>,
308	}
309	
310	impl Out {
311	    fn json(status: u16, v: &Value) -> Self {
312	        Out { status, content_type: "application/json", body: v.to_string(), headers: Vec::new() }
313	    }
314	
315	    fn text(status: u16, body: &str) -> Self {
316	        Out { status, content_type: "text/plain; charset=utf-8", body: body.to_string(), headers: Vec::new() }
317	    }
318	
319	    fn empty(status: u16) -> Self {
320	        Self::text(status, "")
321	    }
322	
323	    fn error(status: u16, msg: &str) -> Self {
324	        Self::json(status, &json!({"error": msg}))
325	    }
326	}
