436	fn route(req: &Request, body: &str, shared: &Shared, session: &mut Session, oauth: Option<&OAuth>) -> Out {
437	    let url = req.url().to_string();
438	    let (path, query) = url.split_once('?').unwrap_or((&url, ""));
439	    let path = if path.len() > 1 { path.trim_end_matches('/') } else { path };
440	    let method = req.method().clone();
441	    let protected = path == "/mcp" || path.starts_with("/v1/");
442	    if protected && method != Method::Options && !authorized(req, shared, oauth) {
443	        return unauthorized(oauth);
444	    }
445	    match (&method, path) {
446	        (Method::Options, _) => Out::empty(204),
447	        (Method::Get, "/") => Out::text(
448	            200,
449	            "Leviathan: MCP at POST /mcp, REST at POST /v1/<tool>, schema at GET /openapi.json\n",
450	        ),
451	        (Method::Get, "/healthz") => {
452	            Out::json(200, &json!({"ok": true, "version": env!("CARGO_PKG_VERSION")}))
453	        }
454	        (Method::Get, "/openapi.json") => Out {
455	            status: 200,
456	            content_type: "application/json",
457	            body: shared.openapi.clone(),
458	            headers: Vec::new(),
459	        },
460	        (Method::Get, p) if p.starts_with("/.well-known/oauth-protected-resource") => {
461	            oauth_only(oauth, |o| Reply::json(200, o.protected_resource_metadata()))
462	        }
463	        (Method::Get, p)
464	            if p.starts_with("/.well-known/oauth-authorization-server")
465	                || p.starts_with("/.well-known/openid-configuration") =>
466	        {
467	            oauth_only(oauth, |o| Reply::json(200, o.authorization_server_metadata()))
468	        }
469	        (Method::Post, "/oauth/register") => oauth_only(oauth, |o| {
470	            o.limited(Limit::Register, &caller(req)).unwrap_or_else(|| o.register(body))
471	        }),
472	        (Method::Get, "/oauth/authorize") => oauth_only(oauth, |o| {
473	            let who = caller(req);
474	            o.limited(Limit::Authorize, &who)
475	                .unwrap_or_else(|| o.authorize_page(&oauth::parse_form(query), &who))
476	        }),
477	        (Method::Post, "/oauth/authorize") => oauth_only(oauth, |o| {
478	            o.limited(Limit::Approve, &caller(req))
479	                .unwrap_or_else(|| o.authorize_submit(&oauth::parse_form(body)))
480	        }),
481	        (Method::Post, "/oauth/token") => oauth_only(oauth, |o| {
482	            o.limited(Limit::Token, &caller(req))
483	                .unwrap_or_else(|| o.token(&oauth::parse_form(body), basic_auth(req)))
484	        }),
485	        (Method::Post, "/mcp") => {
486	            if let Some(v) = header(req, "MCP-Protocol-Version")
487	                && !mcp::PROTOCOL_VERSIONS.contains(&v.trim())
488	            {
489	                return Out::json(
490	                    400,
491	                    &json!({"jsonrpc": "2.0", "id": null, "error": {"code": -32600, "message": format!("unsupported MCP-Protocol-Version {v}")}}),
492	                );
493	            }
494	            match session.handle_body(body) {
495	                Some(reply) => Out::json(200, &reply),
496	                None => Out::empty(202),
497	            }
498	        }
499	        (Method::Get | Method::Delete, "/mcp") => {
500	            let mut out = Out::error(405, "this server answers POST /mcp only");
501	            out.headers.push(("Allow", "POST".into()));
502	            out
503	        }
504	        (Method::Post, p) if p.starts_with("/v1/") => rest(&p[4..], query, body, session),
505	        _ => Out::error(404, "not found"),
506	    }
507	}
