13	/// The bearer token for a remote server: the token file, else the
14	/// environment variable `env` (normally $LEVIATHAN_TOKEN).
15	pub fn client_token(file: Option<&Path>, env: &str) -> Result<Option<String>> {
16	    if let Some(path) = file {
17	        let text =
18	            std::fs::read_to_string(path).with_context(|| format!("read token file {}", path.display()))?;
19	        return Ok(Some(text.trim().to_string()).filter(|t| !t.is_empty()));
20	    }
21	    let token = std::env::var(env).ok().map(|t| t.trim().to_string()).filter(|t| !t.is_empty());
22	    // `wrap` writes a `<your token…>` placeholder into configs.
23	    if token.as_deref().is_some_and(|t| t.starts_with('<')) {
24	        eprintln!(
25	            "[leviathan] ${env} is still the placeholder from `leviathan wrap`; put the real token there"
26	        );
27	        return Ok(None);
28	    }
29	    Ok(token)
30	}
