48	/// POST one JSON-RPC body; collect the replies whether they come back as
49	/// JSON or as an SSE stream.
50	fn post(
51	    agent: &ureq::Agent,
52	    url: &str,
53	    token: Option<&str>,
54	    session_id: Option<&str>,
55	    protocol: Option<&str>,
56	    body: &str,
57	) -> Result<Posted> {
58	    let mut rb = agent
59	        .post(url)
60	        .header("Content-Type", "application/json")
61	        .header("Accept", "application/json, text/event-stream");
62	    if let Some(t) = token {
63	        rb = rb.header("Authorization", format!("Bearer {t}"));
64	    }
65	    if let Some(s) = session_id {
66	        rb = rb.header("Mcp-Session-Id", s);
67	    }
68	    if let Some(p) = protocol {
69	        rb = rb.header("MCP-Protocol-Version", p);
70	    }
71	    let mut resp = rb.send(body).with_context(|| format!("POST {url}"))?;
72	    let status = resp.status().as_u16();
73	    let header = |k: &str| resp.headers().get(k).and_then(|v| v.to_str().ok()).map(str::to_string);
74	    let session_id = header("mcp-session-id");
75	    let sse = header("content-type").is_some_and(|c| c.starts_with("text/event-stream"));
76	    let mut messages = Vec::new();
77	    let mut text = String::new();
78	    if sse {
79	        let reader = BufReader::new(resp.body_mut().as_reader());
80	        let mut data = String::new();
81	        let flush = |data: &mut String, messages: &mut Vec<Value>| {
82	            if let Ok(v) = serde_json::from_str::<Value>(data) {
83	                messages.push(v);
84	            }
85	            data.clear();
86	        };
87	        for line in reader.lines() {
88	            let line = line?;
89	            if line.is_empty() {
90	                flush(&mut data, &mut messages);
91	            } else if let Some(d) = line.strip_prefix("data:") {
92	                if !data.is_empty() {
93	                    data.push('\n');
94	                }
95	                data.push_str(d.strip_prefix(' ').unwrap_or(d));
96	            }
97	        }
98	        flush(&mut data, &mut messages);
99	    } else {
100	        text = resp.body_mut().read_to_string().unwrap_or_default();
101	        if let Ok(v) = serde_json::from_str::<Value>(&text) {
102	            messages.push(v);
103	        }
104	    }
105	    Ok(Posted { status, session_id, messages, body: text })
106	}
