108	/// Call one tool on a remote MCP endpoint and return its text.
109	pub fn call_tool(url: &str, token: Option<&str>, name: &str, args: &Value) -> Result<String> {
110	    let agent = agent(false);
111	    let body = json!({"jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": {"name": name, "arguments": args}});
112	    let posted = post(&agent, url, token, None, None, &body.to_string())?;
113	    if posted.status == 401 {
114	        bail!("{url} refused the token (HTTP 401): set {TOKEN_ENV} or --token-file");
115	    }
116	    if !(200..300).contains(&posted.status) {
117	        bail!("{url}: HTTP {} {}", posted.status, posted.body.chars().take(200).collect::<String>());
118	    }
119	    let reply =
120	        posted.messages.into_iter().find(|m| m.get("id").is_some()).context("no reply from the server")?;
121	    if let Some(err) = reply.get("error") {
122	        bail!("{}", err["message"].as_str().unwrap_or("remote error"));
123	    }
124	    let result = &reply["result"];
125	    let text = result["content"]
126	        .as_array()
127	        .into_iter()
128	        .flatten()
129	        .filter_map(|c| c["text"].as_str())
130	        .collect::<Vec<_>>()
131	        .join("\n");
132	    if result["isError"].as_bool() == Some(true) {
133	        bail!("{}", text.trim_start_matches("error: "));
134	    }
135	    Ok(text)
136	}
