138	fn reply_error(out: &mut impl Write, id: Option<&Value>, text: &str) -> Result<()> {
139	    eprintln!("[leviathan] {text}");
140	    if let Some(id) = id {
141	        writeln!(out, "{}", json!({"jsonrpc": "2.0", "id": id, "error": {"code": -32001, "message": text}}))?;
142	        out.flush()?;
143	    }
144	    Ok(())
145	}
