147	/// `leviathan mcp --remote URL`: a stdio MCP server that forwards every
148	/// message to a remote MCP endpoint, for agents that only speak stdio or
149	/// cannot send headers.
150	pub fn bridge(url: &str, token: Option<&str>) -> Result<()> {
151	    let agent = agent(true);
152	    let mut session_id: Option<String> = None;
153	    let mut protocol: Option<String> = None;
154	    let stdin = std::io::stdin();
155	    let mut stdout = std::io::stdout().lock();
156	    eprintln!("[leviathan] bridging stdio to {url}{}", if token.is_some() { " (with token)" } else { "" });
157	    for line in stdin.lock().lines() {
158	        let line = line?;
159	        if line.trim().is_empty() {
160	            continue;
161	        }
162	        let msg: Value = serde_json::from_str(&line).unwrap_or(Value::Null);
163	        let id = msg.get("id").filter(|_| msg.get("method").is_some());
164	        let is_init = msg.get("method").and_then(Value::as_str) == Some("initialize");
165	        let posted = match post(&agent, url, token, session_id.as_deref(), protocol.as_deref(), &line) {
166	            Ok(p) => p,
167	            Err(err) => {
168	                reply_error(&mut stdout, id, &format!("remote Leviathan unreachable: {err:#}"))?;
169	                continue;
170	            }
171	        };
172	        if posted.status == 401 {
173	            reply_error(
174	                &mut stdout,
175	                id,
176	                &format!("{url} refused the token (HTTP 401): set {TOKEN_ENV} or --token-file"),
177	            )?;
178	            continue;
179	        }
180	        if posted.status == 404 && session_id.is_some() {
181	            session_id = None;
182	        }
183	        if posted.session_id.is_some() {
184	            session_id = posted.session_id;
185	        }
186	        if !(200..300).contains(&posted.status) && posted.messages.is_empty() {
187	            reply_error(&mut stdout, id, &format!("{url}: HTTP {}", posted.status))?;
188	            continue;
189	        }
190	        for m in posted.messages {
191	            if is_init && let Some(v) = m.pointer("/result/protocolVersion").and_then(Value::as_str) {
192	                protocol = Some(v.to_string());
193	            }
194	            writeln!(stdout, "{m}")?;
195	        }
196	        stdout.flush()?;
197	    }
198	    Ok(())
199	}
